from dataclasses import dataclass
from typing import Callable, Dict, Hashable, List, Optional, Sequence

@dataclass(frozen=True)
class RefinementSystem:
    candidates: Sequence[Hashable]
    valid: Callable[[Hashable], bool]
    complexity: Callable[[Hashable], int]
    def refines(self, p_new: Hashable, p_old: Hashable) -> bool:
        return (self.valid(p_new) and self.valid(p_old)
                and self.complexity(p_new) < self.complexity(p_old))
    def global_minimum(self) -> Optional[Hashable]:
        v = [c for c in self.candidates if self.valid(c)]
        return min(v, key=self.complexity) if v else None

def longest_chain(system: RefinementSystem, start: Hashable) -> List[Hashable]:
    chain, current = [start], start
    while True:
        cs = [c for c in system.candidates if system.refines(c, current)]
        if not cs: break
        current = max(cs, key=system.complexity); chain.append(current)
    return chain

weights: Dict[str, int] = {'draft': 9, 'revised': 6, 'tight': 4, 'book': 2}
S = RefinementSystem(list(weights), lambda c: True, lambda c: weights[c])
gmin = S.global_minimum()
chain = longest_chain(S, 'draft')
print('simplest proof:', gmin, 'C =', weights[gmin])
print('chain:', chain, 'steps =', len(chain) - 1, 'bound =', weights['draft'])

from typing import List

def maximal_chain_length(m: int) -> int:
    complexity = {i: i for i in range(m + 1)}
    chain, current = [m], m
    while True:
        cs = [c for c in complexity if complexity[c] < complexity[current]]
        if not cs: break
        current = max(cs, key=lambda c: complexity[c]); chain.append(current)
    return len(chain) - 1

for m in (3, 7, 20, 100):
    steps = maximal_chain_length(m)
    print(f'm = {m:>3}: {steps} steps, bound = {m}, tight = {steps == m}')

